/// The outcome of projecting one object.
pub struct ProjectResult<'a> {
    pub _tab: flatbuffers::Table<'a>,
}

impl<'a> flatbuffers::Follow<'a> for ProjectResult<'a> {
    type Inner = ProjectResult<'a>;
    #[inline]
    unsafe fn follow(buf: &'a [u8], loc: usize) -> Self::Inner {
        Self {
            _tab: flatbuffers::Table::new(buf, loc),
        }
    }
}

impl<'a> ProjectResult<'a> {
    pub const VT_OBJECT_ID: flatbuffers::VOffsetT = 4;
    pub const VT_SOURCE_HASH: flatbuffers::VOffsetT = 6;
    pub const VT_ROWS: flatbuffers::VOffsetT = 8;
    pub const VT_REVISION: flatbuffers::VOffsetT = 10;

    #[inline]
    pub unsafe fn init_from_table(table: flatbuffers::Table<'a>) -> Self {
        ProjectResult { _tab: table }
    }
    #[allow(unused_mut)]
    pub fn create<'bldr: 'args, 'args: 'mut_bldr, 'mut_bldr, A: flatbuffers::Allocator + 'bldr>(
        _fbb: &'mut_bldr mut flatbuffers::FlatBufferBuilder<'bldr, A>,
        args: &'args ProjectResultArgs<'args>,
    ) -> flatbuffers::WIPOffset<ProjectResult<'bldr>> {
        let mut builder = ProjectResultBuilder::new(_fbb);
        builder.add_revision(args.revision);
        builder.add_rows(args.rows);
        if let Some(x) = args.source_hash {
            builder.add_source_hash(x);
        }
        if let Some(x) = args.object_id {
            builder.add_object_id(x);
        }
        builder.finish()
    }

    #[inline]
    pub fn object_id(&self) -> ObjectId<'a> {
        // Safety:
        // Created from valid Table for this object
        // which contains a valid value in this slot
        unsafe {
            self._tab
                .get::<flatbuffers::ForwardsUOffset<ObjectId>>(ProjectResult::VT_OBJECT_ID, None)
                .unwrap()
        }
    }
    #[inline]
    pub fn source_hash(&self) -> &'a str {
        // Safety:
        // Created from valid Table for this object
        // which contains a valid value in this slot
        unsafe {
            self._tab
                .get::<flatbuffers::ForwardsUOffset<&str>>(ProjectResult::VT_SOURCE_HASH, None)
                .unwrap()
        }
    }
    /// Rows written across the main table and relations; 0 when the
    /// (object, source hash) pair was already projected.
    #[inline]
    pub fn rows(&self) -> u32 {
        // Safety:
        // Created from valid Table for this object
        // which contains a valid value in this slot
        unsafe {
            self._tab
                .get::<u32>(ProjectResult::VT_ROWS, Some(0))
                .unwrap()
        }
    }
    /// The revision number the rows carry.
    #[inline]
    pub fn revision(&self) -> u64 {
        // Safety:
        // Created from valid Table for this object
        // which contains a valid value in this slot
        unsafe {
            self._tab
                .get::<u64>(ProjectResult::VT_REVISION, Some(0))
                .unwrap()
        }
    }
}

impl flatbuffers::Verifiable for ProjectResult<'_> {
    #[inline]
    fn run_verifier(
        v: &mut flatbuffers::Verifier,
        pos: usize,
    ) -> Result<(), flatbuffers::InvalidFlatbuffer> {
        use self::flatbuffers::Verifiable;
        v.visit_table(pos)?
            .visit_field::<flatbuffers::ForwardsUOffset<ObjectId>>(
                "object_id",
                Self::VT_OBJECT_ID,
                true,
            )?
            .visit_field::<flatbuffers::ForwardsUOffset<&str>>(
                "source_hash",
                Self::VT_SOURCE_HASH,
                true,
            )?
            .visit_field::<u32>("rows", Self::VT_ROWS, false)?
            .visit_field::<u64>("revision", Self::VT_REVISION, false)?
            .finish();
        Ok(())
    }
}
